CAT = "cpabarGovTransactions"; SEG = "GVT"
Q = [
("A city's capital assets, net, are $90,000,000. Related bonds payable are $52,000,000, of which $4,000,000 of proceeds is unspent and held in cash. Net investment in capital assets is:",
 "$42,000,000", ["$48,000,000", "$90,000,000", "$46,000,000"],
 "Debt tied to unspent proceeds is excluded, so the related debt is $52,000,000 - $4,000,000 = $48,000,000, and $90,000,000 - $48,000,000 = $42,000,000.",
 90000000 - (52000000 - 4000000)),
("A state's total pension liability is $480,000,000 and its pension plan's fiduciary net position is $395,000,000. The net pension liability reported is:",
 "$85,000,000", ["$480,000,000", "$395,000,000", "$875,000,000"],
 "Under GASB Statement 68 the net pension liability is the total pension liability less the plan's fiduciary net position: $480,000,000 - $395,000,000 = $85,000,000.",
 480000000 - 395000000),
("Supplies inventory reported in a general fund's balance sheet is classified in fund balance as:",
 "Nonspendable", ["Restricted", "Committed", "Assigned"],
 "GASB Statement 54 classifies amounts not in spendable form, such as inventories and prepaid items, as nonspendable fund balance."),
("A city council passes an ordinance setting aside general fund resources for park repairs; only another ordinance can remove the limit. The amount is:",
 "Committed fund balance", ["Restricted fund balance", "Assigned fund balance", "Nonspendable fund balance"],
 "Constraints imposed by formal action of the government's highest level of decision-making authority are committed. Restrictions come from outside parties or enabling legislation."),
("A finance director, under authority the council delegated, earmarks general fund resources for next year's software purchase. The amount is reported as:",
 "Assigned fund balance", ["Committed fund balance", "Restricted fund balance", "Unassigned fund balance"],
 "Amounts the government intends for a purpose, set by an official or body given that authority, are assigned. Committed amounts need formal action by the highest authority."),
("A positive unassigned fund balance is reported only in:",
 "The general fund", ["Every governmental fund", "Special revenue funds", "Capital projects funds"],
 "Under GASB Statement 54 the general fund is the only fund that reports a positive unassigned balance. Other governmental funds report unassigned only as a deficit."),
("A general fund's total fund balance is $10,000,000. It holds $300,000 of inventory, $1,200,000 restricted by a grant, $2,000,000 set aside by council ordinance and $1,500,000 earmarked by the city manager under delegated authority. Unassigned fund balance is:",
 "$5,000,000", ["$6,500,000", "$8,500,000", "$5,300,000"],
 "Unassigned is the residual: $10,000,000 - $300,000 nonspendable - $1,200,000 restricted - $2,000,000 committed - $1,500,000 assigned = $5,000,000.",
 10000000 - 300000 - 1200000 - 2000000 - 1500000),
("A city levies $20,000,000 of property taxes for the current year and expects 2% to be uncollectible. In the government-wide statements, property tax revenue for the year is:",
 "$19,600,000", ["$20,000,000", "$400,000", "$18,000,000"],
 "On the accrual basis, imposed nonexchange revenue is recognized for the period for which the taxes are levied, net of estimated uncollectible amounts: $20,000,000 x 98% = $19,600,000.",
 20000000 * 0.98),
("Property taxes a city collects before the start of the period for which they are levied are reported as:",
 "A deferred inflow of resources", ["Revenue when collected", "A liability to taxpayers", "Unassigned fund balance"],
 "GASB Statement 65 reports resources from imposed nonexchange transactions received before the period for which property taxes are levied as deferred inflows."),
("A city receives a reimbursement grant in advance, before it has met the grant's eligibility requirements other than time. It reports the cash received as:",
 "A liability", ["Revenue", "A deferred inflow", "Restricted fund balance"],
 "GASB Statement 65 treats resources received before eligibility requirements other than time are met as liabilities. Only unmet time requirements give a deferred inflow."),
("A general fund issues a purchase order for $25,000 of equipment and records the encumbrance. The equipment arrives with an invoice for $24,600. The expenditure recorded is:",
 "$24,600", ["$25,000", "$25,400", "$49,600"],
 "The encumbrance is reversed for the $25,000 ordered, and the expenditure is recorded at the actual invoice amount of $24,600.",
 24600),
("A city's general fund budget shows estimated revenues of $50,000,000 and appropriations of $48,000,000. In recording the budget, budgetary fund balance is credited for:",
 "$2,000,000", ["$50,000,000", "$48,000,000", "$98,000,000"],
 "The entry debits estimated revenues $50,000,000, credits appropriations $48,000,000 and credits budgetary fund balance for the $2,000,000 difference.",
 50000000 - 48000000),
("The general fund sends $500,000 to the debt service fund to pay bond interest. In the general fund this is reported as:",
 "A transfer out", ["An expenditure", "A loan receivable", "A special item"],
 "A nonreciprocal flow between funds with no repayment is an interfund transfer, an other financing use in the paying fund and an other financing source in the receiving fund."),
("Transfers between two governmental funds are reported in the government-wide statement of activities:",
 "Not at all, as they are eliminated", ["As general revenues", "As transfers in and out", "As program revenues"],
 "Interfund activity within governmental activities is eliminated in the government-wide statements. Only transfers between governmental and business-type activities remain, as transfers."),
("At year end, a city has $150,000 of interest accrued but not yet due on general obligation bonds. The amount the debt service fund recognizes as an expenditure for that interest is:",
 "$0", ["$150,000", "$75,000", "$300,000"],
 "Under the modified accrual basis, principal and interest on general long-term debt are generally recognized as expenditures when due, so the fund recognizes $0 now. The government-wide statements would accrue the interest.",
 0),
("A capital projects fund issues bonds with a face value of $10,000,000 for $10,300,000. The amount it reports as other financing sources is:",
 "$10,300,000", ["$10,000,000", "$300,000", "$0"],
 "Governmental funds report the bond face amount and the premium as other financing sources, $10,000,000 + $300,000 = $10,300,000, and record no long-term liability in the fund.",
 10000000 + 300000),
]
